var CommonTool = module.exports = {};

CommonTool.simulateInterval = function(callback, interval) {
    let timerId = null;
  
    function fn() {
      callback();
      let prevTimmerId = timerId;
      timerId = setTimeout(fn, interval);
      clearTimeout(prevTimmerId);
    }
  
    timerId = setTimeout(fn, interval);
    return function(){
      if(timerId != null)
      {
        clearTimeout(timerId);
        timerId = null;
      }    
    };
};